def word_count(text):
    words = re.findall(r"[A-Za-z0-9']+", text)
    count_dict = {}
    for word in words:
        lower_word = word.lower()
        count_dict[lower_word] = count_dict.get(lower_word, 0) + 1
    return count_dict

