            # No overlap, add the current interval
            merged.append([current_start, current_end])

    return merged

def two_sum(nums, target):
    """
    Returns a tuple (i, j) with i < j such that nums[i] + nums[j] == target,
    choosing the pair with the smallest j (and then the smallest i).
    Returns None if no such pair exists.
    """
    seen = {}  # value -> smallest index seen so far
    for j, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            i = seen[complement]
            if i < j:
                return (i, j)
        # Always store the smallest index for a given value
        if num not in seen:
            seen[num] = j
    return None

def caesar(text, shift):
    result = []
    for char in text:
        if 'A' <= char <= 'Z':
            # Uppercase letter
            new_char = chr((ord(char) - ord('A') + shift) % 26 + ord('A'))
            result.append(new_char)
        elif 'a' <= char <= 'z':
            # Lowercase letter
            new_char = chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
            result.append(new_char)
        else:
            # Non-letter character, keep unchanged
            result.append(char)
    return ''.join(result)

def caesar(text: str, shift: int) -> str:
    def shift_char(c: str) -> str:
        if not ('a' <= c <= 'z' or 'A' <= c <= 'Z'):
            return c
        is_upper = 'A' <= c <= 'Z'
        base = ord('A') if is_upper else ord('a')
        offset = ord(c) - base
        new_offset = (offset + shift) % 26
        return chr(base + new_offset)

    return ''.join(shift_char(c) for c in text)

